-- CI-043 v2.2 rev b MANDATORY POST-CHECK (+ run verify_ci043v22_post_rpc.sql). Pass/fail rows test MIGRATION CORRECTNESS only: baseline unchanged, objects/ACLs/no anon, STABLE/definer, settings values, function executes with valid severities, known run-119 WARN REFERENCE_FINGERPRINT_DRIFT present (functional test, valid while the baseline is unchanged). If any pass/fail row fails: run 20261027093000_ci043v22_ROLLBACK.sql, then re-run the pre-check (read-only).
-- Rows starting 'INFO' (pass = NULL) are an OPERATIONAL diagnostic: every ERROR/WARN finding the health function returns. They do NOT fail the post-check and never trigger rollback; a real operational ERROR (e.g. job 68 stopped) is reported and investigated separately. Baseline literals: production 27 Oct 2026 18:10 IST (after CI-042 v2.2).
with chk(check_name, expected, actual) as (
  select 'H01 combined fingerprint 119/122/143', '3e5515ed97189b747ea3a8d18c3f4411', (select md5(string_agg(md5(costing.fn_compute_run_fingerprint(r)::text),'|' order by r)) from unnest(array[119,122,143]) r)
  union all select 'H02 queued/running runs', '0', (select count(*)::text from costing.costing_refresh_run where overall_status in ('QUEUED','RUNNING'))
  union all select 'H03 runs count/max', '118/143', (select count(*)||'/'||max(id) from costing.costing_refresh_run)
  union all select 'H04 audit rows count/max id', '17/21', (select count(*)||'/'||max(audit_id) from costing.cost_period_governance_audit)
  union all select 'H05 designation rows count/max id', '9/11', (select count(*)||'/'||max(id) from costing.costing_run_designation)
  union all select 'H06 fingerprint rows count/max id', '28/30', (select count(*)||'/'||max(id) from costing.costing_run_fingerprint)
  union all select 'H07 effective designations', '119=REFERENCE,122=APPROVED,128=REVOKED,136=REVOKED,140=REVOKED,143=APPROVED', (select string_agg(refresh_run_id||'='||designation, ',' order by refresh_run_id) from costing.v_costing_run_effective_designation)
  union all select 'H08 periods', '2026-03-01:OPEN:2026-03-31 2026-06-01:OPEN:2026-06-30 2026-07-01:OPEN:2026-07-22 2026-08-01:OPEN:2026-08-07 2026-09-01:LOCKED:2026-09-10 2026-10-01:OPEN:2026-10-22', (select string_agg(period_start||':'||status||':'||valuation_date, ' ' order by period_start) from costing.cost_periods)
  union all select 'H17 cron 66/67/68 command md5 unchanged (active state is operational -> INFO via JOB_INACTIVE)', '66:0045bba6068cf31ac53852d6b743a745 67:0045bba6068cf31ac53852d6b743a745 68:c3b74bfc510dd2b4dc061217ff43eef6', (select string_agg(jobid||':'||md5(command), ' ' order by jobid) from cron.job where jobid in (66,67,68))
  union all select 'H20 CI-043 objects present', 'costing.fn_costing_health_check(date),rpc_costing_health_check()', concat_ws(',', to_regprocedure('costing.fn_costing_health_check(date)'), to_regprocedure('public.rpc_costing_health_check()'))
  union all select 'H21 settings rows (3 existing unchanged + 9 health_*)', 'approval_preview_ack_ttl_minutes=15,health_draft_freshness_days=8,health_draft_review_days=14,health_preview_ack_unused_min_age_days=30,health_preview_ack_unused_warn_count=50,health_quarter_lock_info_days=30,health_quarter_lock_warn_days=45,health_queued_stuck_hours=2,health_retry_overdue_minutes=20,health_running_stuck_hours=6,scheduler_catch_up_max_runs=1,scheduler_max_retries=2', (select string_agg(setting_key||'='||int_value, ',' order by setting_key collate "C") from costing.costing_automation_setting)
  union all select 'H22 ACL internal fn (owner only) | RPC (authenticated, service_role)', '{postgres=X/postgres} | {postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}', (select proacl::text from pg_proc where oid='costing.fn_costing_health_check(date)'::regprocedure)||' | '||(select proacl::text from pg_proc where oid='public.rpc_costing_health_check()'::regprocedure)
  union all select 'H22b anon cannot execute either function', 'false', (has_function_privilege('anon','costing.fn_costing_health_check(date)','execute') or has_function_privilege('anon','public.rpc_costing_health_check()','execute'))::text
  union all select 'H22c both SECURITY DEFINER, owner postgres, STABLE (read-only)', 'postgres true s x2', (select max(proowner::regrole||' '||prosecdef||' '||provolatile::text)||' x'||count(*) from pg_proc where oid in ('costing.fn_costing_health_check(date)'::regprocedure,'public.rpc_costing_health_check()'::regprocedure) having count(distinct proowner::regrole||' '||prosecdef||' '||provolatile::text)=1)
  union all select 'H23 health check runs; every severity is ERROR/WARN/INFO (no count assertion)', 'true', (select coalesce(bool_and(severity in ('ERROR','WARN','INFO')), true)::text from costing.fn_costing_health_check(null))
  union all select 'H23c expected production finding: WARN REFERENCE_FINGERPRINT_DRIFT for run 119', 'true', (select exists (select 1 from costing.fn_costing_health_check(null) where check_code='REFERENCE_FINGERPRINT_DRIFT' and severity='WARN' and run_id=119)::text)
  union all select 'H23b comment says reports only, sends no alerts', 'true', (obj_description('public.rpc_costing_health_check()'::regprocedure,'pg_proc') like '%reports only; sends no alerts%')::text
  union all select 'H24 NO new cron job (count / max id unchanged)', '34/68', (select count(*)||'/'||max(jobid) from cron.job)
  union all select 'H25 CI-042 objects unchanged (lock / batch lock / views md5 present)', 'true', (to_regprocedure('public.rpc_costing_lock_periods_for_close(date[],text,text)') is not null and to_regclass('public.v_costing_pricing_run_display_status') is not null)::text
)
select check_name, expected, actual, coalesce(expected = actual, false) pass from chk
union all select 'ALL POST-CHECKS PASS', 'true', (select bool_and(coalesce(expected=actual,false))::text from chk), (select bool_and(coalesce(expected=actual,false)) from chk)
union all select 'INFO operational findings (diagnostic only, not a migration check)', '', (select count(*)::text||' ERROR/WARN' from costing.fn_costing_health_check(null) where severity in ('ERROR','WARN')), null::boolean
union all (select 'INFO '||severity||' '||check_code, coalesce(period_start::text,'')||coalesce(' run '||run_id,''), left(detail,200), null::boolean from costing.fn_costing_health_check(null) where severity in ('ERROR','WARN') order by severity, check_code, run_id);
